mapper.select:
select
mn.*,pro.P_Name as pName,pro.P_Name as projectName,com.C_Name as prPayCName
from Payment_Receipt mn
left join Pre_Project pro on pro.P_ID = mn.Project_Id
left join SYS_Company com on com.C_ID = mn.Pr_Pay_C_Id
${params.authSql}
and mn.Pr_Method is not null and mn.Pr_Issued_State!=5 and mn.Pr_Verify_State!=4

    and mn.Project_Id = #{params.projectId}


    
        
            and likePname(#{params.pName},pro.P_Id)=true
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    and mn.Pr_Issued_State = #{params.prIssuedState}


    and mn.Pr_Verify_State = #{params.prVerifyState}


    and mn.Pr_Verify_State in
    
        #{state}
    


    and mn.State = #{params.state}


    and mn.receipt_Unwritten_Amount > 0


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.create_time DESC

